using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Data; using SmartCampusServicePortal.Models; namespace SmartCampusServicePortal.Controllers; [ApiController,Route("api/servicerequests")] public class ServiceRequestsApiController(ApplicationDbContext db):ControllerBase{[HttpGet] public async Task<IActionResult> All()=>Ok(await db.ServiceRequests.ToListAsync()); [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var r=await db.ServiceRequests.FindAsync(id);return r==null?NotFound():Ok(r);} [HttpPost] public async Task<IActionResult> Post(ServiceRequest r){r.Id=0;r.SubmissionDate=DateTime.Now;r.Status="Pending";db.Add(r);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=r.Id},r);} [HttpPut("{id:int}")] public async Task<IActionResult> Put(int id,ServiceRequest input){var r=await db.ServiceRequests.FindAsync(id);if(r==null)return NotFound();r.StudentName=input.StudentName;r.StudentRollNo=input.StudentRollNo;r.Category=input.Category;r.Description=input.Description;r.Status=input.Status;r.AdminRemarks=input.AdminRemarks;await db.SaveChangesAsync();return Ok(r);} [HttpPut("{id:int}/status")] public async Task<IActionResult> Status(int id,StatusUpdateDto d){var r=await db.ServiceRequests.FindAsync(id);if(r==null)return NotFound();r.Status=d.Status;r.AdminRemarks=d.AdminRemarks??r.AdminRemarks;await db.SaveChangesAsync();return Ok(r);} [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var r=await db.ServiceRequests.FindAsync(id);if(r==null)return NotFound();db.Remove(r);await db.SaveChangesAsync();return NoContent();}}